import {
  chainTriggerProps,
  TriggerAnchor,
} from "@/wab/client/components/widgets/TriggerAnchor";
import {
  DefaultFilterButtonProps,
  PlasmicFilterButton,
} from "@/wab/client/plasmic/plasmic_kit_left_pane/PlasmicFilterButton";
import { mergeRefs } from "@/wab/commons/components/ReactUtil";
import { Dropdown, Tooltip } from "antd";
import * as React from "react";

export interface FilterButtonProps extends DefaultFilterButtonProps {
  tooltip?: React.ReactNode;
  popupRender?: React.ComponentProps<typeof Dropdown>["popupRender"];
}

function FilterButton(props: FilterButtonProps) {
  const { tooltip, popupRender, ...rest } = props;
  // Both triggers anchor on the button itself: the tooltip's hover handlers
  // and ref would otherwise stop at the Dropdown element.
  return (
    <Tooltip title={tooltip}>
      <TriggerAnchor>
        {(tooltipRef, tooltipProps) => (
          <Dropdown popupRender={popupRender} trigger={["click"]}>
            <TriggerAnchor>
              {(dropdownRef, dropdownProps) => (
                <PlasmicFilterButton
                  {...chainTriggerProps(
                    tooltipProps,
                    chainTriggerProps(dropdownProps, rest),
                  )}
                  root={{ ref: mergeRefs(tooltipRef, dropdownRef) }}
                />
              )}
            </TriggerAnchor>
          </Dropdown>
        )}
      </TriggerAnchor>
    </Tooltip>
  );
}

export default FilterButton;
